import React, {useState} from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  Image,
  StyleSheet,
  ScrollView,
  Pressable,
} from 'react-native';
import {nav, switchTgl, notif, upLoad} from '../assets/img/Images';
import {Picker} from '@react-native-picker/picker';
import CheckBox from '@react-native-community/checkbox';

const AddFood = ({navigation}) => {
  const [selectedLanguage, setSelectedLanguage] = useState(
    (catFood = [
      {label: 'Football', value: 'football'},
      {label: 'Baseball', value: 'baseball'},
      {label: 'Hockey', value: 'hockey'},
    ]),
  );

  const [breakTime, setBreakTime] = useState(false);
  const [lunchTime, setLunchTime] = useState(false);
  const [dinnerTime, setDinnerTime] = useState(false);

  return (
    <ScrollView>
      <View
        style={{
          height: 55,
          backgroundColor: '#09b44d',
        }}>
        <View
          style={{
            padding: 1,
            flexDirection: 'row',
            justifyContent: 'space-between',
            alignItems: 'center',
          }}>
          <View
            style={{
              flexDirection: 'row',
            }}>
            <TouchableOpacity
              onPress={() => navigation.toggleDrawer()}
              style={{
                paddingHorizontal: 15,
                paddingVertical: 15,
              }}>
              <Image style={{width: 28, height: 20}} source={nav} />
            </TouchableOpacity>

            <TouchableOpacity>
              <Text style={[styles.pageTitle, {alignItems: 'center'}]}>
                Homee Foodz
              </Text>
            </TouchableOpacity>
          </View>

          <View
            style={{
              flexDirection: 'row',
              justifyContent: 'flex-end',
              alignItems: 'center',
            }}>
            <TouchableOpacity style={{paddingHorizontal: 10}}>
              <Image source={switchTgl} style={{width: 38, height: 22}} />
            </TouchableOpacity>
            <TouchableOpacity style={{paddingRight: 20, paddingLeft: 10}}>
              <Image source={notif} style={{width: 22, height: 26}} />
              <Text style={styles.notifCnt}>25</Text>
            </TouchableOpacity>
          </View>
        </View>
      </View>

      <View
        style={{
          paddingHorizontal: 15,
          marginTop: 10,
          justifyContent: 'center',
        }}>
        <View style={styles.inputBox}>
          <Text style={styles.labelTxt}>Food Categories</Text>
          <Picker
            style={styles.dropselect}
            selectedValue={selectedLanguage}
            onValueChange={(itemValue, itemIndex) =>
              setSelectedLanguage(itemValue)
            }>
            {catFood.map((item, index) => {
              return (
                <Picker.Item
                  key={index}
                  label={item.label}
                  value={item.value}
                />
              );
            })}
          </Picker>
        </View>
        <View style={styles.inputBox}>
          <Text style={styles.labelTxt}>Cusion Type</Text>
          <Picker
            style={styles.dropselect}
            selectedValue={selectedLanguage}
            onValueChange={(itemValue, itemIndex) =>
              setSelectedLanguage(itemValue)
            }>
            {catFood.map((item, index) => {
              return (
                <Picker.Item
                  key={index}
                  label={item.label}
                  value={item.value}
                />
              );
            })}
          </Picker>
        </View>
        <View style={styles.inputBox}>
          <Text style={styles.labelTxt}>Food Name</Text>
          <Picker
            style={styles.dropselect}
            selectedValue={selectedLanguage}
            onValueChange={(itemValue, itemIndex) =>
              setSelectedLanguage(itemValue)
            }>
            {catFood.map((item, index) => {
              return (
                <Picker.Item
                  key={index}
                  label={item.label}
                  value={item.value}
                />
              );
            })}
          </Picker>
        </View>
      </View>

      <View
