              marginTop: 9,
              color: '#000',
              fontSize: 15,
              fontFamily: 'Poppins-Regular',
            }}>
            BreakFast
          </Text>
        </View>
        <View style={{flexDirection: 'row', marginHorizontal: 10}}>
          <CheckBox
            disabled={false}
            value={lunchTime}
            onValueChange={newValue => setLunchTime(newValue)}
          />
          <Text
            style={{
              marginTop: 9,
              color: '#000',
              fontSize: 15,
              fontFamily: 'Poppins-Regular',
            }}>
            Lunch
          </Text>
        </View>
        <View style={{flexDirection: 'row', marginHorizontal: 10}}>
          <CheckBox
            disabled={false}
            value={dinnerTime}
            onValueChange={newValue => setDinnerTime(newValue)}
          />
          <Text
            style={{
              marginTop: 9,
              color: '#000',
              fontSize: 15,
              fontFamily: 'Poppins-Regular',
            }}>
            Dinner
          </Text>
        </View>
      </View>

      <View style={{paddingVertical: 15, paddingHorizontal: 15}}>
        <TouchableOpacity
          onPress={() => {
            cameraHandle();
          }}
          style={{
            width: '100%',
            backgroundColor: '#c6edd5',
            borderRadius: 10,
            justifyContent: 'center',
            alignItems: 'center',
            height: 150,
          }}>
          <Image
            source={upLoad}
            style={{
              width: 65,
